def make_styles():
    styles = getSampleStyleSheet()
    return {
        "kicker": ParagraphStyle("Kicker", parent=styles["Normal"], fontName="Helvetica-Bold", fontSize=8.5, leading=10, textColor=colors.HexColor("#2E74B5"), spaceAfter=8),
        "title": ParagraphStyle("FixtureTitle", parent=styles["Title"], fontName="Helvetica-Bold", fontSize=20, leading=24, textColor=colors.HexColor("#0B2545"), alignment=TA_LEFT, spaceAfter=10),
        "body": ParagraphStyle("FixtureBody", parent=styles["BodyText"], fontName="Helvetica", fontSize=10.2, leading=14, textColor=colors.HexColor("#243447"), spaceAfter=8),
        "label": ParagraphStyle("Label", parent=styles["BodyText"], fontName="Helvetica-Bold", fontSize=9.2, leading=11, textColor=colors.HexColor("#0B2545")),
        "small": ParagraphStyle("Small", parent=styles["BodyText"], fontName="Helvetica", fontSize=8.5, leading=10, textColor=colors.HexColor("#51606F")),
    }


def header_footer(canvas, doc):
    canvas.saveState()
    width, height = letter
    canvas.setStrokeColor(colors.HexColor("#D7E0EA"))
    canvas.setLineWidth(0.6)
    canvas.line(0.75 * inch, height - 0.62 * inch, width - 0.75 * inch, height - 0.62 * inch)
    canvas.setFont("Helvetica-Bold", 8)
    canvas.setFillColor(colors.HexColor("#51606F"))
    canvas.drawString(0.75 * inch, height - 0.48 * inch, "NORTHSTAR SERVICE LAB | TEST FIXTURE")
    canvas.setFont("Helvetica", 8)
    canvas.drawRightString(width - 0.75 * inch, 0.48 * inch, f"Customer Service Manual | Page {doc.page}")
    canvas.line(0.75 * inch, 0.62 * inch, width - 0.75 * inch, 0.62 * inch)
    canvas.restoreState()


def build():
    styles = make_styles()
    frame = Frame(0.85 * inch, 0.82 * inch, 6.8 * inch, 9.35 * inch, leftPadding=0.12 * inch, rightPadding=0.12 * inch, topPadding=0.05 * inch, bottomPadding=0.05 * inch, id="normal")
    doc = BaseDocTemplate(str(PDF_PATH), pagesize=letter, leftMargin=0.75 * inch, rightMargin=0.75 * inch, topMargin=0.75 * inch, bottomMargin=0.75 * inch, title="Customer Service Test Fixture", author="Northstar Service Lab")
    doc.addPageTemplates([PageTemplate(id="fixture", frames=[frame], onPage=header_footer)])
    story = []
    for index, (title, overview, bullets, rows) in enumerate(SECTIONS, start=1):
        story.append(Paragraph(f"CUSTOMER SERVICE | MODULE {index:02d}", styles["kicker"]))
        story.append(Paragraph(title, styles["title"]))
        story.append(Paragraph(overview, styles["body"]))
        story.append(Paragraph("Operational checks", styles["label"]))
        for bullet in bullets:
            story.append(Paragraph(f"- {bullet}", styles["body"]))
        story.append(Spacer(1, 4))
        table_data = [[Paragraph(str(cell), styles["label"] if r == 0 else styles["small"]) for cell in row] for r, row in enumerate(rows)]
        table = Table(table_data, colWidths=[2.0 * inch, 4.55 * inch], hAlign="LEFT")
        table.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#E8EEF5")),
            ("GRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#B8C6D4")),
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ("LEFTPADDING", (0, 0), (-1, -1), 8),
            ("RIGHTPADDING", (0, 0), (-1, -1), 8),
            ("TOPPADDING", (0, 0), (-1, -1), 6),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
        ]))
        story.append(table)
        story.append(Spacer(1, 10))
        story.append(Paragraph(f"Fixture marker: CS-FIXTURE-40 | Module {index:02d} | Synthetic content for application testing", styles["small"]))
        if index != len(SECTIONS):
            story.append(PageBreak())
    doc.build(story)
    print(f"created {PDF_PATH}")


if __name__ == "__main__":
    build()
